<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { http } from "@/utils/http";
import { localForage } from "@/utils/localforage";

type Row = Record<string, any>;
const deviceId = ref(""); const resourceId = ref(""); const attachmentId = ref(""); const kind = ref("DOWNLOAD"); const tab = ref("cache"); const cache = ref<Row[]>([]); const downloads = ref<Row[]>([]); const completedOnly = ref(false); const loading = ref(false); const saving = ref(false); const error = ref(""); const message = ref(""); const queried = ref(false); const offlineStatus = ref<Record<string, string>>({});
const visibleDownloads = computed(() => completedOnly.value ? downloads.value.filter(row => row.kind === "DOWNLOAD" && row.state === "COMPLETED") : downloads.value);
function localCopyKey(row: Row) { return `offline-download:${row.id}`; }
async function refreshOfflineStatus(rows: Row[]) { const statuses = await Promise.all(rows.map(async row => { if (row.kind !== "DOWNLOAD" || row.state !== "COMPLETED") return [String(row.id), "不可用"] as const; try { const copy = await localForage().getItem<{ blob?: Blob }>(localCopyKey(row)); return [String(row.id), copy?.blob ? "离线可用" : "未准备"] as const; } catch { return [String(row.id), "读取失败"] as const; } })); offlineStatus.value = Object.fromEntries(statuses); }
function offlineStatusType(row: Row) { const status = offlineStatus.value[String(row.id)]; return status === "离线可用" ? "success" : status === "未准备" ? "warning" : status === "读取失败" ? "danger" : "info"; }
async function load() { if (!deviceId.value.trim()) { error.value = "请输入 Device ID"; return; } loading.value = true; error.value = ""; try { const query = `?deviceId=${encodeURIComponent(deviceId.value.trim())}`; const [c, d] = await Promise.all([http.get<unknown, unknown>(`/offline/cache${query}`), http.get<unknown, unknown>(`/offline/downloads${query}`)]); cache.value = Array.isArray(c) ? c as Row[] : []; downloads.value = Array.isArray(d) ? d as Row[] : []; queried.value = true; await refreshOfflineStatus(downloads.value); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "缓存与下载数据加载失败"; } finally { loading.value = false; } }
async function createDownload() { if (!deviceId.value.trim() || !resourceId.value.trim()) { error.value = "Device ID 和 Resource ID 不能为空"; return; } saving.value = true; error.value = ""; message.value = ""; try { await http.post("/offline/downloads", { data: { deviceId: deviceId.value.trim(), resourceId: resourceId.value.trim(), attachmentId: attachmentId.value.trim() || undefined, kind: kind.value } }); message.value = "下载任务已创建，状态为 QUEUED"; resourceId.value = ""; attachmentId.value = ""; tab.value = "downloads"; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "下载任务创建失败"; } finally { saving.value = false; } }
async function removeDownload(row: Row) { if (!row.id || !window.confirm("确认移除此下载记录？不会删除服务端 Resource 或 Blob。")) return; error.value = ""; try { await localForage().removeItem(localCopyKey(row)); await http.request("delete", `/offline/downloads/${row.id}`); delete offlineStatus.value[String(row.id)]; message.value = "下载记录及本机离线副本已移除"; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "下载记录移除失败"; } }
onMounted(() => { });
</script>
<template><main class="p-4 md:p-6"><div class="flex flex-wrap justify-between gap-4 mb-6"><div><h1 class="text-2xl font-semibold">缓存与我的下载</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">管理服务端缓存和客户端下载元数据，不展示客户端私有路径。</p></div><div class="flex gap-2"><el-input v-model="deviceId" placeholder="Device ID" clearable @keyup.enter="load"/><el-button type="primary" :loading="loading" @click="load">查询</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><el-alert v-if="message" :title="message" type="success" show-icon :closable="false" class="mb-4"/><el-card shadow="never"><el-tabs v-model="tab"><el-tab-pane label="服务端缓存" name="cache"><div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4"><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">缓存对象</div><div class="text-2xl font-semibold mt-2">{{ cache.length }}</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">缓存字节数</div><div class="text-2xl font-semibold mt-2">{{ cache.reduce((sum, row) => sum + Number(row.sizeBytes || 0), 0).toLocaleString() }}</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">状态</div><div class="mt-2">仅影响缓存，不影响持久化数据</div></el-card></div><el-empty v-if="!queried" description="输入 Device ID 查询缓存"/><el-empty v-else-if="!cache.length" description="暂无服务端缓存"/><el-table v-else :data="cache" stripe><el-table-column prop="resourceId" label="Resource" min-width="220"/><el-table-column prop="attachmentId" label="Attachment" min-width="220"/><el-table-column prop="sizeBytes" label="大小（Bytes）" width="140"/><el-table-column prop="state" label="状态" width="140"/><el-table-column prop="lastAccessedAt" label="最近访问" min-width="180"/></el-table></el-tab-pane><el-tab-pane label="客户端下载" name="downloads"><el-card shadow="never" class="mb-4"><template #header><span>创建下载任务</span></template><div class="flex flex-wrap gap-3 items-end"><el-form-item label="Resource ID" required><el-input v-model="resourceId" class="w-72" clearable/></el-form-item><el-form-item label="Attachment ID"><el-input v-model="attachmentId" class="w-72" clearable/></el-form-item><el-form-item label="类型"><el-select v-model="kind" class="w-40"><el-option label="明确下载" value="DOWNLOAD"/><el-option label="缓存" value="CACHE"/></el-select></el-form-item><el-button type="primary" :loading="saving" @click="createDownload">创建任务</el-button></div><p class="mt-2 text-sm text-[var(--el-text-color-secondary)]">任务属于当前 Device；创建后由客户端执行，服务端状态会在重新查询后更新。</p></el-card><div class="mb-3"><el-checkbox v-model="completedOnly">仅显示已完成的明确下载</el-checkbox></div><el-empty v-if="!queried" description="输入 Device ID 查询下载"/><el-empty v-else-if="!visibleDownloads.length" description="暂无符合条件的下载记录"/><el-table v-else :data="visibleDownloads" stripe><el-table-column prop="deviceId" label="设备" min-width="220"/><el-table-column prop="resourceId" label="Resource" min-width="220"/><el-table-column prop="attachmentId" label="Attachment" min-width="220"/><el-table-column prop="kind" label="类型" width="130"/><el-table-column prop="state" label="状态" width="140"/><el-table-column label="离线状态" width="130"><template #default="{ row }"><el-tag :type="offlineStatusType(row)">{{ offlineStatus[String(row.id)] || "检查中" }}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="下载时间" min-width="180"/><el-table-column label="操作" width="120"><template #default="{ row }"><el-button v-if="row.kind === 'DOWNLOAD' && row.state !== 'REMOVED'" link type="danger" @click="removeDownload(row)">移除</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></el-card></main></template>
